export type ParsedLiquidatePositionInstruction<
  TProgram extends string = typeof SOLFX_CORE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /**
     * Anyone. Publishing the liquidator source and encouraging third parties is the
     * resilient design (§ 9.2) — a permissionless liquidation market does not have an
     * on-call rota.
     */
    liquidator: TAccountMetas[0];
    protocol: TAccountMetas[1];
    /**
     * The position's owner. Any residual equity is returned to them — a liquidation takes
     * the penalty, not the account.
     */
    userAccount: TAccountMetas[2];
    market: TAccountMetas[3];
    /**
     * Closed and its rent returned to the position owner, not to the liquidator. The
     * liquidator is paid from the penalty; taking the rent as well would be taking the
     * trader's deposit.
     */
    position: TAccountMetas[4];
    rentDestination: TAccountMetas[5];
    /** The liquidator's share is credited here, so they need no prior account with us. */
    liquidatorTokenAccount: TAccountMetas[6];
    collateralVault: TAccountMetas[7];
    lpPool: TAccountMetas[8];
    lpVault: TAccountMetas[9];
    insuranceFund: TAccountMetas[10];
    insuranceVault: TAccountMetas[11];
    feeVault: TAccountMetas[12];
    priceUpdate: TAccountMetas[13];
    secondaryPriceUpdate?: TAccountMetas[14] | undefined;
    quoteConversionPriceUpdate?: TAccountMetas[15] | undefined;
    tokenProgram: TAccountMetas[16];
  };
  data: LiquidatePositionInstructionData;
};

export function parseLiquidatePositionInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedLiquidatePositionInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 17) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === SOLFX_CORE_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      liquidator: getNextAccount(),
      protocol: getNextAccount(),
      userAccount: getNextAccount(),
      market: getNextAccount(),
      position: getNextAccount(),
      rentDestination: getNextAccount(),
      liquidatorTokenAccount: getNextAccount(),
      collateralVault: getNextAccount(),
      lpPool: getNextAccount(),
      lpVault: getNextAccount(),
      insuranceFund: getNextAccount(),
      insuranceVault: getNextAccount(),
      feeVault: getNextAccount(),
      priceUpdate: getNextAccount(),
      secondaryPriceUpdate: getNextOptionalAccount(),
      quoteConversionPriceUpdate: getNextOptionalAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getLiquidatePositionInstructionDataDecoder().decode(instruction.data),
  };
}
